\section{Introduction}

Advice about where to look usually comes as nested confidence statements: ``probably in the first ten, almost surely in the first thirty.'' We call such advice a \emph{multi-window oracle} and ask two questions. Which search order is optimal? And for which window menus $(w_i,\alpha_i)$ can some order beat a reference price by a factor $s$?

For a single window the answer is the classical \emph{crossing law}: a window of relative width $w$ and reliability $\alpha$ supports speedup $s$ exactly when $w\le\alpha-\alpha_{\min}(s)$. Our main result, the \emph{multi-window crossing law}, extends this to any number of nested windows. Reachability is one linear inequality in the reliabilities, and it is equivalent to a lower bound on the area under a piecewise-linear reliability curve. The key tool is a layer-cake displacement law: the cost of any order is a sum of block-weight jumps times index sums of upper sets.

\section{The model}

Fix $M\ge1$ and cells $0,\dots,M-1$. A \emph{search order} is a bijection $\sigma$ from cells to slots $\{0,\dots,M-1\}$. For a probability vector $p$, the \emph{probe cost} is
\[
C(p,\sigma)=\sum_{j=0}^{M-1}\bigl(\sigma(j)+1\bigr)p_j .
\]
The \emph{committed order} is the identity.

A \emph{menu} with $n\ge1$ blocks consists of integers $0=B_0<B_1<\cdots<B_n=M$ and reals $0=A_0\le A_1\le\cdots\le A_n=1$. The named windows are $[0,B_i)$ for $1\le i\le k:=n-1$, with reliabilities $\alpha_i=A_i$. The blocks are $[B_i,B_{i+1})$, and the last block is the \emph{complement} of the widest window. It carries mass $1-\alpha_k$.

\begin{definition}[Step posterior]
Let $d_i=(A_{i+1}-A_i)/(B_{i+1}-B_i)$ and set $p_j=d_i$ for $B_i\le j<B_{i+1}$.
\end{definition}

\begin{definition}[Calibration]
The menu is \emph{calibrated} if $d_0\ge d_1\ge\cdots\ge d_{n-1}$.
\end{definition}

\begin{definition}[Gate functional]
With $x_i=B_i/M$,
\[
\Phi(x,A)=\sum_{i=0}^{n-1}(A_{i+1}-A_i)\,\frac{x_i+x_{i+1}}{2}.
\]
\end{definition}

\begin{definition}[Pricing and speedup]
The reference price is $\beta_M=\frac{(M+1)(2M+1)}{6M}=\frac1{M^2}\sum_{t=1}^Mt^2\sim\frac M3$. An order \emph{achieves speedup} $s>0$ if $s\,C(p,\sigma)\le\beta_M$. A speedup is \emph{reachable} if some order achieves it.
\end{definition}

\section{The committed cost}

\begin{theorem}[Committed cost of a step posterior]\label{thm:committed}
For every menu,
\[
C(p,\id)=\sum_{i=0}^{n-1}(A_{i+1}-A_i)\cdot\frac{B_i+B_{i+1}+1}{2},
\]
where $\tfrac12(B_i+B_{i+1}+1)$ is the mean $1$-based slot of block $i$.
\end{theorem}
\begin{proof}[Proof sketch]
Split the sum by blocks and use $\sum_{j=B_i}^{B_{i+1}-1}(j+1)=\tfrac12(B_{i+1}-B_i)(B_i+B_{i+1}+1)$, which follows by induction. Multiplying by $d_i$ cancels the width.
\end{proof}

\begin{corollary}[Normalised committed cost]\label{cor:norm}
$C(p,\id)=M\,\Phi(x,A)+\tfrac12(A_n-A_0)=M\,\Phi(x,A)+\tfrac12$.
\end{corollary}
\begin{proof}[Proof sketch]
Write $\tfrac12(B_i+B_{i+1}+1)=M\tfrac{x_i+x_{i+1}}2+\tfrac12$. The constants telescope.
\end{proof}

\section{The layer-cake law and Bayes-optimality}

For an order $\sigma$ let $S_\sigma(m)=\sum_{j<m}(\sigma(j)+1)$.

\begin{lemma}[Exchange-sum bound]\label{lem:exchange}
$S_\sigma(m)\ge m(m+1)/2$, with equality if and only if $\sigma$ maps $[0,m)$ onto $\{0,\dots,m-1\}$.
\end{lemma}
\begin{proof}[Proof sketch]
The sum of $m$ distinct positive integers is at least $1+\dots+m$, with equality only for $\{1,\dots,m\}$.
\end{proof}

\begin{theorem}[Layer-cake displacement law]\label{thm:layer}
For a calibrated step posterior, with $d_n:=0$, and any order $\sigma$,
\[
C(p,\sigma)=\sum_{i=0}^{n-1}(d_i-d_{i+1})\,S_\sigma(B_{i+1}),\qquad d_i-d_{i+1}\ge0 .
\]
\end{theorem}
\begin{proof}[Proof sketch]
Write $p_j=\sum_i(d_i-d_{i+1})\mathbf 1[j<B_{i+1}]$; for $j$ in block $r$ the surviving terms telescope to $d_r$. Then exchange the order of summation.
\end{proof}

\begin{theorem}[Bayes-optimality of committed search]\label{thm:bayes}
For a calibrated menu, $C(p,\id)\le C(p,\sigma)$ for all $M!$ orders $\sigma$. If the densities are strictly decreasing, equality holds exactly for the orders that permute cells within blocks.
\end{theorem}
\begin{proof}[Proof sketch]
Combine Theorem~\ref{thm:layer} with Lemma~\ref{lem:exchange}. All the $S_\sigma(B_{i+1})$ are minimised simultaneously by the identity.
\end{proof}

\section{The crossing law}

\begin{theorem}[Exact finite gate]\label{thm:exact}
For a calibrated menu and $s>0$: some order achieves speedup $s$ if and only if $s\bigl(M\Phi+\tfrac12\bigr)\le\beta_M$.
\end{theorem}
\begin{proof}[Proof sketch]
The minimum cost is $C(p,\id)$ by Theorem~\ref{thm:bayes}, and this equals $M\Phi+\tfrac12$ by Corollary~\ref{cor:norm}.
\end{proof}

\begin{theorem}[Continuum limit]\label{thm:limit}
For $\Phi>0$ and any real $c$, $\displaystyle\lim_{M\to\infty}\frac{\beta_M}{M\Phi+c}=\frac1{3\Phi}$.
\end{theorem}
\begin{proof}[Proof sketch]
$\beta_M/(M\Phi+c)=\frac{(1+1/M)(2+1/M)/6}{\Phi+c/M}\to\frac{1}{3\Phi}$.
\end{proof}

\begin{definition}
The continuum speedup of a profile is $s^\ast=1/(3\Phi)$. Speedup $s$ is continuum-reachable if $s\le s^\ast$.
\end{definition}

\begin{theorem}[Multi-window crossing law]\label{thm:main}
For $s>0$,
\[
s\le\frac1{3\Phi}\iff\Phi\le\frac1{3s}\iff\sum_{i=0}^{n-1}(A_{i+1}-A_i)\frac{x_i+x_{i+1}}2\le\frac1{3s}.
\]
The sum runs over the $k$ named blocks \emph{and} the complement block.
\end{theorem}
\begin{proof}[Proof sketch]
$\Phi>0$ (see Theorem~\ref{thm:auc}), so take reciprocals.
\end{proof}

\section{The area form and the single-window law}

Let $F$ be the piecewise-linear curve through $(0,0),(x_1,A_1),\dots,(1,1)$, and let $\AUC=\int_0^1F$.

\begin{theorem}[Gate functional plus area]\label{thm:auc}
$\Phi(x,A)+\AUC=x_nA_n-x_0A_0=1$. In particular $0<\Phi<1$.
\end{theorem}
\begin{proof}[Proof sketch]
By the trapezoid rule, the $i$th terms of $\Phi$ and $\AUC$ add up to $x_{i+1}A_{i+1}-x_iA_i$, which telescopes (summation by parts).
\end{proof}

\begin{corollary}[AUC crossing law]
Speedup $s$ is continuum-reachable if and only if $\AUC\ge1-\frac1{3s}$.
\end{corollary}

\begin{corollary}[Single-window crossing law]
For $n=2$ with $w=x_1$ and $\alpha=A_1$, we have $\Phi=\tfrac12(w+1-\alpha)$, and $s$ is reachable if and only if $w\le\alpha-\alpha_{\min}(s)$, where $\alpha_{\min}(s)=1-\frac2{3s}$.
\end{corollary}

\section{Structural consequences}

\begin{theorem}[Outer reliability gate]
If $s$ is continuum-reachable, then $\alpha_k\ge\alpha_{\min}(s)+w_k(1-\alpha_k)$, where $w_k=x_{n-1}$ and $\alpha_k=A_{n-1}$. In particular $\alpha_k>\alpha_{\min}(s)$ when $w_k>0$ and $\alpha_k<1$.
\end{theorem}
\begin{proof}[Proof sketch]
Monotonicity gives $F\le\alpha_k$ on $[0,w_k]$, so $\AUC\le\alpha_kw_k+(1-w_k)\frac{1+\alpha_k}{2}$. Compare with $1-\frac1{3s}=\frac{1+\alpha_{\min}(s)}{2}$.
\end{proof}

\begin{theorem}[Refinement identity]
Inserting $(x',\alpha')$ between consecutive corners $(x_\ell,\alpha_\ell)$ and $(x_r,\alpha_r)$ changes $\Phi$ by
\[
-\frac{(x_r-x_\ell)\bigl(\alpha'-\chord(x')\bigr)}{2},\qquad \chord(x')=\alpha_\ell+(\alpha_r-\alpha_\ell)\frac{x'-x_\ell}{x_r-x_\ell}.
\]
\end{theorem}
\begin{proof}[Proof sketch]
$\Delta\Phi=-\Delta\AUC$, and the area changes by the signed area of the inserted triangle.
\end{proof}

\begin{corollary}
A new window helps (strictly lowers $\Phi$) if and only if it lies strictly above the chord of its neighbours.
\end{corollary}

\begin{proposition}[Affinity, convexity, monotonicity]
For fixed $x$, $A\mapsto\Phi(x,A)$ is affine, so the reachable reliability profiles form a convex polyhedron. Moreover $\partial\Phi/\partial A_i=-\tfrac12(x_{i+1}-x_{i-1})<0$ and $\partial\Phi/\partial x_i=\tfrac12(A_{i+1}-A_{i-1})\ge0$.
\end{proposition}

\begin{example}[Oracle design as a linear program]
Fix $x=(0,\frac16,\frac12,1)$ and leave $\alpha_1,\alpha_2$ free. Then $\Phi=\frac34-\frac14\alpha_1-\frac5{12}\alpha_2$, so the gate for $s$ is the half-plane $\frac14\alpha_1+\frac5{12}\alpha_2\ge\frac34-\frac1{3s}$ intersected with the calibration cone $6\alpha_1\ge3(\alpha_2-\alpha_1)\ge2(1-\alpha_2)$. For $s=\frac32$: with $\alpha_2=\frac56$ one needs $\alpha_1\ge\frac{13}{18}$, and with $\alpha_1=\frac12$ one needs $\alpha_2\ge\frac{29}{30}$. Both choices are calibrated and respect the outer gate $\alpha_2\ge\frac{19}{27}$.
\end{example}

\begin{remark}
Since $\Phi=1-\AUC$, we have $0<\Phi<1$. Calibrated curves are concave, so $\Phi\le\frac12$ and $s^\ast\ge\frac23$. Under strictly decreasing densities there are exactly $\prod_i(B_{i+1}-B_i)!$ optimal orders.
\end{remark}

\section{The hypotheses are needed}

\begin{proposition}[Calibration cannot be dropped]
For $M=6$ with blocks $[0,3)$ and $[3,6)$ of masses $\frac1{10}$ and $\frac9{10}$, the reversed order costs $\frac{23}{10}$, while committed search costs $\frac{47}{10}$.
\end{proposition}
\begin{proof}
Committed: $\frac1{10}\cdot2+\frac9{10}\cdot5$. Reversed: $\frac1{10}\cdot5+\frac9{10}\cdot2$.
\end{proof}

\begin{proposition}[The complement block is indispensable]
The naive gate over the named windows only is false. For $k=1$, $w=\frac12$, $\alpha=\frac1{10}$ and $s=1$, the naive sum is $\frac1{40}\le\frac13$, but $\Phi=\frac7{10}>\frac13$.
\end{proposition}

\section{A worked instance}

\begin{example}
Let $M=6$, $B=(0,1,3,6)$ and $A=(0,\frac12,\frac56,1)$. The densities $\frac12,\frac16,\frac1{18}$ are decreasing. The committed cost is $\frac12\cdot1+\frac13\cdot\frac52+\frac16\cdot5=\frac{13}6$, and it is optimal among all $720$ orders; exactly $12$ orders attain it. Here $\Phi=\frac5{18}$, $\AUC=\frac{13}{18}$ and $\beta_6=\frac{91}{36}$. The best speedup at $M=6$ is $\frac76$, and the continuum speedup is $\frac65$. Scaling to $M=60,600,6000$ gives approximately $1.19434$, $1.19940$ and $1.19994$.
\end{example}

\section{Algorithms}

\emph{Gate test:} compute $\Phi$ in $O(n)$ time, then check $s(M\Phi+\frac12)\le\beta_M$ and $\Phi\le1/(3s)$.
\emph{Bayes order:} sort the blocks by density in $O(n\log n)$ time and emit cells block by block.
\emph{Refinement screening:} find the neighbours by binary search and evaluate the chord identity.

\section{Discussion}

The gate is linear in the oracle's claims, so oracle design becomes a linear program. The area form ties the theory to ROC-style evaluation. Three classical tools underlie the results: the rearrangement inequality, the layer-cake representation, and summation by parts. In the multi-window setting the upper level sets of the step posterior are exactly the named windows, which is why the final criterion is linear in the stated reliabilities. The gate depends only on the reliability polygon; a window on the chord of its neighbours carries no value. The structural results do not depend on the pricing convention; only the constant $1/(3s)$ does.

\section{Open problems}

\begin{problem}[Concave-majorant Bayes gate]
For non-calibrated step posteriors, show that the Bayes speedup is governed by the AUC of the concave rearrangement of the reliability curve.
\end{problem}
\begin{problem}[Refinement monotonicity]
Show that inserting a calibrated window never lowers the speedup, and strictly raises it off the chord.
\end{problem}
\begin{problem}[Optimal $k$-window menus]
For a concave reliability curve, show that the optimal $k$-window loss in AUC is $\Theta(1/k^2)$.
\end{problem}
\begin{problem}[Two-sided gate]
Show that the Bayes-reachable set is a union of polyhedra indexed by the density orders of the blocks.
\end{problem}

