from __future__ import annotations
from fractions import Fraction as Fr
from typing import Sequence, Tuple


def gate_functional(x: Sequence[Fr], A: Sequence[Fr]) -> Fr:
    """Phi = sum_i (A_{i+1} - A_i) (x_i + x_{i+1}) / 2, complement block included."""
    return sum(((A[i + 1] - A[i]) * (x[i] + x[i + 1]) / 2 for i in range(len(x) - 1)), Fr(0))


def reference_price(M: int) -> Fr:
    """beta_M = (M+1)(2M+1)/(6M)."""
    return Fr((M + 1) * (2 * M + 1), 6 * M)


def is_calibrated(B: Sequence[int], A: Sequence[Fr]) -> bool:
    d = [(A[i + 1] - A[i]) / (B[i + 1] - B[i]) for i in range(len(B) - 1)]
    return all(d[i] >= d[i + 1] for i in range(len(d) - 1))


def multi_window_gate(B: Sequence[int], A: Sequence[Fr], s: Fr) -> Tuple[bool, bool, Fr]:
    """Return (finite verdict, continuum verdict, Phi) for menu (B, A) and target speedup s.

    B = (0, B_1, ..., B_{n-1}, M) strictly increasing, A = (0, A_1, ..., A_{n-1}, 1).
    The finite verdict is exact for calibrated menus.
    """
    M = B[-1]
    x = [Fr(b, M) for b in B]
    phi = gate_functional(x, A)
    finite = s * (M * phi + Fr(1, 2)) <= reference_price(M)
    continuum = phi <= 1 / (3 * s)
    return finite, continuum, phi


if __name__ == "__main__":
    B, A = [0, 1, 3, 6], [Fr(0), Fr(1, 2), Fr(5, 6), Fr(1)]
    assert is_calibrated(B, A)
    for s in [Fr(1), Fr(7, 6), Fr(6, 5), Fr(5, 4)]:
        print(s, multi_window_gate(B, A, s))
